            ['leave', 'سياسة طلب الإجازات', 'الموارد البشرية', 'يقدم الموظف طلب الإجازة عبر النظام مع النوع والفترة. مدة الإشعار التنظيمية: [مدة الإشعار]. تراجع الموارد البشرية الاستحقاق وفق القانون والعقد المعمول بهما، ويعتمد المسؤول الطلب. توثق الحالات الطارئة والاستثناءات ولا تنتقص هذه السياسة من الحقوق القانونية. تحدد الشركة بعد المراجعة أنواع الإجازات والاستحقاقات وشروط الترحيل.', [$hr]],
            ['conduct', 'سياسة السلوك المهني', 'الموارد البشرية', 'يلتزم الفريق بالاحترام وعدم التمييز وحماية معلومات الشركة. تقدم الشكاوى إلى [جهة استقبال الشكاوى] بسرية وبلا انتقام. توثق الوقائع وتتاح فرصة الرد قبل القرار. تخضع الإجراءات التأديبية لمراجعة مختصة وفق القانون والعقود؛ لا تفرض هذه المسودة عقوبات محددة.', [$hr]],
            ['customer-followup', 'سياسة متابعة العملاء', 'المبيعات', 'يسجل كل عميل في النظام مع مسؤول المتابعة ومصدره. زمن الرد المستهدف: [زمن الرد]. توثق محاولات التواصل والنتائج والخطوة التالية وتحدث مرحلة الفرصة. يراجع المدير الفرص المتأخرة دوريًا، ويحترم الفريق طلبات عدم التواصل. لا يقدم وعودًا غير معتمدة.', [$sales]],
            ['discounts', 'سياسة الخصومات والموافقات', 'المبيعات', 'تحدد قائمة الأسعار المعتمدة العملة وتاريخ السريان. حد الخصم الذي يتطلب موافقة: [حد الخصم]. يوثق المندوب السبب والهامش المتوقع ويطلب اعتماد المسؤول قبل إرسال العرض. تسجل الاستثناءات ومدتها. عند التسعير بالدولار يوثق سعر الصرف ومصدره وتاريخه؛ لا يغير العرض المقبول دون اتفاق.', [$sales]],
            ['commissions', 'سياسة عمولات المبيعات', 'المبيعات', 'تحدد الشركة كتابيًا أساس احتساب العمولة: [أساس العمولة]، والنسبة أو المعادلة: [معادلة العمولة]. توثق شروط الاستحقاق والتحصيل والمرتجعات وفترة المراجعة، ويراجع الموظف الحساب قبل الاعتماد. لا ينشئ النظام استحقاقًا أو صرفًا تلقائيًا. تراجع الشروط مع المختص قبل التطبيق.', [$hr, $sales]],
            ['expenses', 'سياسة المصروفات', 'الإدارة', 'يتطلب المصروف غرضًا مهنيًا ومستندًا مؤيدًا. حد الموافقة المسبقة: [حد الموافقة]. تقدم المطالبة إلى المسؤول وتراجع محاسبيًا قبل الصرف. توثق الاستثناءات والعملات وسعر التحويل. يحدد موعد تقديم المطالبات: [موعد تقديم المطالبات]. لا يصرف مبلغ بلا اعتماد.', []],
            ['ai-use', 'سياسة استخدام الذكاء الاصطناعي', 'الإدارة', 'يستخدم TAIE لدعم التحليل والإجابة من المصادر المصرح بها. لا ترفع أسرارًا أو بيانات شخصية دون تفويض ومراجعة إعدادات المعالجة. تصنف المستندات وتحدد صلاحياتها. يراجع الإنسان الإجابات ومصادرها قبل القرار، ولا يعامل المقترح كسياسة نافذة. تبلغ الأخطاء إلى [جهة الإبلاغ]. يعتمد المسؤول أي تغيير رسمي.', []],
            ['onboarding', 'قائمة تجهيز الموظف الجديد', 'أدلة العمل', 'قبل المباشرة: مراجعة العقد والمستندات مع المختص، وإعداد القسم والمسمى والمدير المباشر. يوم المباشرة: تعريف الموظف بالمهام والسياسات المعتمدة ومنحه الصلاحيات اللازمة فقط. موعد جلسة المتابعة: [موعد جلسة المتابعة]. يوثق المسؤول تسليم الأجهزة والتدريب وملاحظات المتابعة.', [$hr]],
        ];

        return array_map(fn ($r) => ['key' => $r[0], 'title' => $r[1], 'category' => $r[2], 'version' => '1.0', 'references' => $r[4], 'notice' => 'قالب أصلي إرشادي من TAIE، وليس نسخة سياسة شركة أخرى أو إثبات امتثال قانوني. أكمل الحقول وراجعه حسب نشاط الشركة والاختصاص المحلي قبل الاعتماد.', 'body' => "الشركة: [اسم الشركة]\nمسؤول الاعتماد: [مسؤول الاعتماد]\nتاريخ السريان: [تاريخ السريان]\n\n".$r[3]."\n\nتراجع هذه السياسة عند تغير الإجراءات أو المتطلبات، وتبلغ النسخة المعتمدة للموظفين المعنيين."], $rows);
